local component = require('component') while 1 do local me = component.me_interface for _,w in ipairs({{1024,'Titanium Ingot'},{1024,'Stainless Steel Ingot'},{1024,'Steel Ingot'},{1024,'Aluminium Ingot'},{32,'Any LV Circuit'},{32,'Any MV Circuit'},{32,'Any HV Circuit'},{32,'Any EV Circuit'},{16,'Lapotron Crystal'},{16,'Energy Crystal'},{512,'ME Glass Cable - Fluix'},{64,'ME Dense Covered Cable - Fluix'},{256,'Item Conduit'},{256,'Ender Fluid Conduit'},{64,'Blank Pattern'},{4,'Nitric Acid Cell'},{4,'Formic Acid Cell'},{16,'Fuel Rod (Glowstone)'},{512,'Black Steel Ingot'},{64,'Quad Fuel Rod (Thorium)'},{512,'Diamond Plate'},}) do local targetAmount, v = w[1],w[2] local pp for z,item in ipairs(me.getCraftables({label=v})) do os.sleep(0.5) pp=z local innet = me.getItemsInNetwork({label=v}) if innet[1] and innet[1].size >= targetAmount then break end local r = item.request(1) while r.isComputing() do os.sleep(0.05) end _ = (r.hasFailed() or print('Requested ' .. v)) and component.chat_box.say('Cant request ' .. v) while not r.isDone() and not r.isCanceled() do os.sleep(0.1) end _ = r.isDone() and print('Crafted ' .. v) end _ = pp or print('Unknown item ' .. v) end end